-- Called from the `clangd_config` target's on_config; writes <projectdir>/.clangd.
-- Keep these lists in sync with the platform remove_files/add_files in
-- hitagi/engine/xmake.lua and hitagi/interop/xmake.lua.
local platform_only_paths = {
    windows = {
        "hitagi/engine/gfx/dx12/.*",
        "hitagi/interop/(dx12|d3d12ma|tracy_dx12|win32)\\.cppm",
    },
    macosx = {
        "hitagi/engine/gfx/metal/.*",
        "hitagi/interop/(metal|spirv_cross)\\.cppm",
        "hitagi/interop/metal\\.cpp",
    },
}

local base_config = [[
# Generated by xmake/scripts/generate_clangd.lua during `xmake config`; do not edit.
CompileFlags:
  Add: [-std=c++23]
  # xmake rewrites these BMIs on every build, which invalidates clangd's own module cache.
  Remove: [-fmodule-file=*]
Diagnostics:
  # Tweak Clang-Tidy checks.
  ClangTidy:
    Add:
      [
        performance*,
        modernize*,
        bugprone-use-after-move,
        cppcoreguidelines-avoid-goto,
        cppcoreguidelines-prefer-member-initializer,
        cppcoreguidelines-avoid-c-arrays,
      ]
    Remove:
      [
        modernize-use-trailing-return-type,
        modernize-use-nodiscard,
        performance-no-int-to-ptr,
        performance-enum-size,
      ]
  UnusedIncludes: Strict

---
If:
  PathMatch: xmake/packages/.*
Index:
  Background: Skip
Diagnostics:
  Suppress: "*"
  ClangTidy:
    Remove: "*"
]]

local excluded_block = [[

---
# Sources that are not compiled on %s, so clangd has no command or modules for them.
If:
  PathMatch:
%s
Index:
  Background: Skip
Diagnostics:
  Suppress: "*"
  ClangTidy:
    Remove: "*"
]]

function main(plat)
    local excluded = {}
    for other_plat, paths in table.orderpairs(platform_only_paths) do
        if other_plat ~= plat then
            table.join2(excluded, paths)
        end
    end

    local content = base_config
    if #excluded > 0 then
        local lines = {}
        for _, pattern in ipairs(excluded) do
            table.insert(lines, string.format("    - %s", pattern))
        end
        content = content .. string.format(excluded_block, plat, table.concat(lines, "\n"))
    end

    local clangd_file = path.join(os.projectdir(), ".clangd")
    if not os.isfile(clangd_file) or io.readfile(clangd_file) ~= content then
        io.writefile(clangd_file, content)
        cprint("${dim}generated %s for %s", clangd_file, plat)
    end
end
